# Search for turn 1 and tool calls
results = await CONTEXT.search("[turn 1]")
for r in results['items']:
    print(f"offset={r['offset']}, snippet={r['snippet'][:300]}")

print("\n\n== tool calls in turn 1 ==")
results = await CONTEXT.search("[tool 1]")
for r in results['items']:
    print(f"offset={r['offset']}, snippet={r['snippet'][:300]}")

print("\n\n== tool calls ==")
for i in range(1, 15):
    results = await CONTEXT.search(f"[tool {i}]")
    if results['items']:
        for r in results['items']:
            print(f"[tool {i}] offset={r['offset']}: {r['snippet'][:200]}")
